(()=>{let lang='en';try{lang=localStorage.getItem('experimental-portfolio-language')==='zh'?'zh':'en'}catch{}const pageTitles={Projects:'项目',Writing:'写作',CV:'履历',About:'关于','Other Work':'其他创作','Page not found':'页面不存在'};function apply(value){document.documentElement.lang=value==='zh'?'zh-CN':'en';document.querySelectorAll('[data-en][data-zh]').forEach(el=>el.textContent=el.dataset[value]);document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===value)));const page=document.body.dataset.pageEn;document.title=(value==='zh'?(pageTitles[page]||page):page)+' — Weiyi Wang';document.querySelector('meta[name=description]').content=value==='zh'?'项目、写作与其他创作。':'Selected projects, writing and other work.';document.querySelector('header nav').setAttribute('aria-label',value==='zh'?'主导航':'Main navigation');document.querySelector('aside nav')?.setAttribute('aria-label',value==='zh'?'项目章节':'Project sections');try{localStorage.setItem('experimental-portfolio-language',value)}catch{}}document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>apply(b.dataset.lang)));apply(lang);})();

try{document.documentElement.dataset.theme=localStorage.getItem('experimental-weiyi-theme')==='night'?'night':'day';}catch{}

document.querySelectorAll('[data-model-scroll]').forEach(button=>button.addEventListener('click',()=>{const track=button.closest('.model-entry').querySelector('.model-carousel');const slide=track.querySelector('figure');track.scrollBy({left:Number(button.dataset.modelScroll)*(slide.getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap)),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
